mapper.select:

WHERE scope = #{scope}
  AND tenant_id IS NOT DISTINCT FROM #{tenantId}::uuid
  AND policy_id = #{policyId}::uuid


WHERE scope = #{scope}
  AND tenant_id IS NOT DISTINCT FROM #{tenantId}::uuid
  AND policy_level = #{policyLevel}
  AND COALESCE(resource_kind, '') = COALESCE(#{resourceKind}, '')
  AND COALESCE(resource_id, '') = COALESCE(#{resourceId}, '')
LIMIT 1
